package edu.daa.dna.controller;
import edu.daa.dna.model.ApiModels.*;import edu.daa.dna.parser.FastaParser;import edu.daa.dna.service.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class ApiController {private final AnalysisService analysis;private final BenchmarkService benchmark;private final FastaParser fasta;public ApiController(AnalysisService a,BenchmarkService b,FastaParser f){analysis=a;benchmark=b;fasta=f;}@PostMapping("/analyze")public AnalysisResponse analyze(@RequestBody AnalyzeRequest q){return analysis.analyze(q);}@PostMapping("/benchmark")public BenchmarkResponse benchmark(@RequestBody BenchmarkRequest q){return benchmark.run(q);}@PostMapping("/fasta")public List<FastaRecord> fasta(@RequestBody Map<String,String> q){return fasta.parse(q.get("content"));}@ExceptionHandler({IllegalArgumentException.class})public ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}}
